// ====== CONFIG — update these to match your FareHarbor Google Sheet's column headers ======
const FIELD = {
  bookingCreatedDate: 'Booking Date',   // when the booking was made
  tourDate: 'Tour Date',                // when the tour actually happens
  guestCount: 'Guest Count',            // number of people on the booking
  totalPrice: 'Total Price',            // $ amount of the booking
  status: 'Status'                      // e.g. "Confirmed", "Cancelled"
};
// ===============================================================================

const now = new Date();
const windowStart = new Date(now.getTime() - 24 * 60 * 60 * 1000);

const allBookings = $input.all().map(item => item.json);

function parseDate(value) {
  const d = new Date(value);
  return isNaN(d.getTime()) ? null : d;
}

const newBookings = allBookings.filter(row => {
  const d = parseDate(row[FIELD.bookingCreatedDate]);
  return d && d >= windowStart && d <= now;
});

const cancellations = newBookings.filter(row =>
  String(row[FIELD.status] || '').toLowerCase().includes('cancel')
);

const activeNewBookings = newBookings.filter(row =>
  !String(row[FIELD.status] || '').toLowerCase().includes('cancel')
);

const revenueLast24h = activeNewBookings.reduce((sum, row) => {
  const price = parseFloat(row[FIELD.totalPrice]) || 0;
  return sum + price;
}, 0);

const guestsLast24h = activeNewBookings.reduce((sum, row) => {
  const guests = parseInt(row[FIELD.guestCount]) || 0;
  return sum + guests;
}, 0);

const sevenDaysOut = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);
const upcomingWeek = allBookings.filter(row => {
  const d = parseDate(row[FIELD.tourDate]);
  const isCancelled = String(row[FIELD.status] || '').toLowerCase().includes('cancel');
  return d && d >= now && d <= sevenDaysOut && !isCancelled;
});

const guestsUpcomingWeek = upcomingWeek.reduce((sum, row) => {
  return sum + (parseInt(row[FIELD.guestCount]) || 0);
}, 0);

// Plain-English flags — add more rules here over time as new things become worth flagging
const flags = [];
if (newBookings.length === 0) {
  flags.push('No new bookings in the last 24 hours.');
}
if (cancellations.length > 0) {
  flags.push(`${cancellations.length} cancellation(s) in the last 24 hours.`);
}
if (upcomingWeek.length === 0) {
  flags.push('No tours currently scheduled in the next 7 days.');
}

const dateLabel = now.toISOString().slice(0, 10);

const contextRow = {
  Date: dateLabel,
  'New Bookings (24h)': newBookings.length,
  'Cancellations (24h)': cancellations.length,
  'Revenue Booked (24h)': revenueLast24h.toFixed(2),
  'Guests Booked (24h)': guestsLast24h,
  'Tours Next 7 Days': upcomingWeek.length,
  'Guests Next 7 Days': guestsUpcomingWeek,
  'Needs Attention': flags.length ? flags.join(' ') : 'Nothing unusual — business as normal.',
  // Placeholder columns — stay blank until the partner-tracking, guide-scheduling and
  // review-monitoring skills are built, then each becomes its own branch feeding this node.
  'Partner Confirmations Outstanding': '',
  'Guide Coverage Gaps': '',
  'New Reviews (24h)': ''
};

const telegramSummary =
  `📊 Louisville Food Tours — Daily Context (${dateLabel})\n\n` +
  `New bookings: ${newBookings.length} (${guestsLast24h} guests, $${revenueLast24h.toFixed(2)})\n` +
  `Cancellations: ${cancellations.length}\n` +
  `Next 7 days: ${upcomingWeek.length} tours, ${guestsUpcomingWeek} guests\n\n` +
  (flags.length ? `⚠️ ${flags.join(' ')}` : '✅ Nothing unusual.');

return [{ json: { ...contextRow, telegram_summary: telegramSummary } }];
